import{reader}from"./reader.min.js";import{navigation}from"./navigation.min.js";import{pwa}from"./pwa.min.js";import{photoGallery}from"./photoGallery.min.js";import{bookmarks}from"./bookmarks.min.js";import{bossButton}from"./boss-button.min.js";import{auth}from"./auth.min.js";import{CHAPTERS}from"../data/chapters.js";class App{constructor(){this.isReady=!1,this.bookmarkBtn=null,this.currentChapterId=1}init(){"loading"===document.readyState?document.addEventListener("DOMContentLoaded",()=>this.checkAuth()):this.checkAuth()}checkAuth(){auth.init()?this.start():window.addEventListener("authSuccess",()=>this.start(),{once:!0})}start(){try{reader.init(),navigation.init(),pwa.init(),photoGallery.init(),bossButton.init(),this.initBookmarkButton(),this.initHomeLink(),this.isReady=!0,window.dispatchEvent(new Event("appReady"))}catch(t){console.error("Failed to initialize app:",t),this.showError("Failed to load the app. Please refresh the page.")}}initHomeLink(){const t=document.getElementById("homeLink");t&&t.addEventListener("click",t=>{t.preventDefault(),history.pushState(null,null,window.location.pathname),window.dispatchEvent(new HashChangeEvent("hashchange"))})}initBookmarkButton(){if(this.bookmarkBtn=document.getElementById("bookmarkBtn"),!this.bookmarkBtn)return;"false"===localStorage.getItem("admin_allowBookmarks")?this.bookmarkBtn.style.display="none":(this.bookmarkBtn.addEventListener("click",()=>{const t=CHAPTERS.find(t=>t.id===this.currentChapterId);if(t){let o=null,e=null;if(window.readerInstance){const t=window.readerInstance.getPaginationInfo();t.totalPages>0&&(o=t.currentPage,e=t.totalPages)}const a=bookmarks.toggleBookmark(t.id,t.title,o,e);this.updateBookmarkButtonState(a)}}),window.addEventListener("chapterLoaded",t=>{this.currentChapterId=t.detail.chapterId,this.updateBookmarkButtonState(bookmarks.isBookmarked(this.currentChapterId))}),window.addEventListener("bookmarksChanged",()=>{this.updateBookmarkButtonState(bookmarks.isBookmarked(this.currentChapterId))}),this.updateBookmarkButtonState(bookmarks.isBookmarked(this.currentChapterId)))}updateBookmarkButtonState(t){this.bookmarkBtn&&(t?(this.bookmarkBtn.classList.add("active"),this.bookmarkBtn.setAttribute("aria-label","Remove bookmark")):(this.bookmarkBtn.classList.remove("active"),this.bookmarkBtn.setAttribute("aria-label","Bookmark chapter")))}showError(t){const o=document.createElement("div");o.className="error",o.textContent=t,document.body.insertBefore(o,document.body.firstChild)}}const app=new App;app.init(),"undefined"!=typeof window&&(window.app=app);